export function applyWelcomeEdits(blocks: any[], uid: () => string) {
  let diagram = 0;
  for (const block of blocks) {
    if (block.type !== 'diagram') continue;
    const saved = edits[diagram++];
    if (!saved) continue;
    const shapes = structuredClone(saved), ids = new Map<string, string>();
    for (const shape of shapes) { ids.set(shape.id, uid()); if (shape.g && !ids.has(shape.g)) ids.set(shape.g, uid()); }
    for (const shape of shapes) {
      shape.id = ids.get(shape.id);
      if (shape.g) shape.g = ids.get(shape.g);
      for (const key of ['link1', 'link2']) if (shape[key]?.id && ids.has(shape[key].id)) shape[key].id = ids.get(shape[key].id);
    }
    block.shapes = shapes;
  }
  return blocks;
}
